const totals = new Map<string, number>();
for (const row of rows) {
  if (row.status !== "paid") continue;
  const revenue = row.quantity * row.unitPrice * (1 - (row.discount ?? 0));
  totals.set(row.country, (totals.get(row.country) ?? 0) + revenue);
}
return Array.from(totals, ([country, total]) => ({ country, total })).sort(
  (a, b) => b.total - a.total || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0)
);

const totals = new Map<string, number>();
for (const row of rows) {
  if (row.status !== "paid") continue;
  const revenue = row.quantity * row.unitPrice * (1 - (row.discount ?? 0));
  const previous = totals.get(row.country);
  totals.set(row.country, previous === undefined ? revenue : previous + revenue);
}
return Array.from(totals, ([country, total]) => ({ country, total })).sort(
  (a, b) => b.total - a.total || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0)
);

const totals = new Map<string, number>();
for (const row of rows) {
  if (row.status !== "paid") continue;
  const revenue = Number((row.quantity * row.unitPrice * (1 - (row.discount ?? 0))).toPrecision(15));
  const previous = totals.get(row.country);
  totals.set(row.country, previous === undefined ? revenue : Number((previous + revenue).toPrecision(15)));
}
return Array.from(totals, ([country, total]) => ({ country, total })).sort(
  (a, b) => b.total - a.total || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0)
);

