// Drafted by the AI and approved by the user.
// Counts paid rows, applies discounts, groups by country, and sorts totals from highest to lowest.
test("paid_rows_grouped_and_sorted", () => {
  const rows: Row[] = [
    { id: 1, orderDate: "2024-01-01", customer: "A", email: "a@example.com", country: "Canada", product: "P", quantity: 2, unitPrice: 10, discount: 0.25, status: "paid" },
    { id: 2, orderDate: "2024-01-02", customer: "B", email: "b@example.com", country: "Brazil", product: "Q", quantity: 1, unitPrice: 30, discount: null, status: "paid" },
    { id: 3, orderDate: "2024-01-03", customer: "C", email: "c@example.com", country: "Canada", product: "R", quantity: 1, unitPrice: 4, discount: null, status: "paid" },
    { id: 4, orderDate: "2024-01-04", customer: "D", email: "d@example.com", country: "Japan", product: "S", quantity: 1, unitPrice: 100, discount: null, status: "pending" }
  ];
  eq(revenueByCountry(rows), [{ country: "Brazil", total: 30 }, { country: "Canada", total: 19 }]);
});

// Keeps every country with equal totals and orders tied totals alphabetically.
test("ties_alphabetical_and_all_countries_included", () => {
  const rows: Row[] = [
    { id: 1, orderDate: "2024-01-01", customer: "A", email: "a@example.com", country: "Zulu", product: "P", quantity: 1, unitPrice: 5, discount: null, status: "paid" },
    { id: 2, orderDate: "2024-01-02", customer: "B", email: "b@example.com", country: "Alpha", product: "Q", quantity: 1, unitPrice: 5, discount: null, status: "paid" }
  ];
  eq(revenueByCountry(rows), [{ country: "Alpha", total: 5 }, { country: "Zulu", total: 5 }]);
});

// Returns an empty array when the table has no rows.
test("empty_input_returns_empty_array", () => {
  eq(revenueByCountry([]), []);
});

// Includes a whitespace-only country value and preserves the exact calculated total without rounding.
test("blank_country_is_included_and_no_rounding", () => {
  const rows: Row[] = [
    { id: 1, orderDate: "2024-01-01", customer: "A", email: "a@example.com", country: " ", product: "P", quantity: 3, unitPrice: 1.01, discount: 0.1, status: "paid" }
  ];
  eq(revenueByCountry(rows), [{ country: " ", total: 2.727 }]);
});

