// Drafted by the AI and approved by the user.
// Adding a row whose status is not paid does not change the revenue totals.
property("unpaid_rows_do_not_change_answer", [fc.array(fc.record({ id: fc.integer(), orderDate: fc.constantFrom("2024-01-01"), customer: fc.string(), email: fc.string(), country: fc.string(), product: fc.string(), quantity: fc.integer({ min: 0, max: 20 }), unitPrice: fc.integer({ min: 0, max: 100 }), discount: fc.constantFrom(null, 0, 0.25, 0.5), status: fc.constantFrom("paid", "pending", "cancelled") }))], rows => {
  const unpaid = rows.map((row, index) => ({ ...row, id: row.id + index, status: "pending" }));
  return JSON.stringify(revenueByCountry(rows)) === JSON.stringify(revenueByCountry([...rows, ...unpaid]));
}, { numRuns: 200 });

// Adding another copy of each paid row adds its revenue again, including for duplicate rows.
property("duplicating_paid_rows_doubles_totals", [fc.array(fc.record({ id: fc.integer(), orderDate: fc.constantFrom("2024-01-01"), customer: fc.string(), email: fc.string(), country: fc.string(), product: fc.string(), quantity: fc.integer({ min: 0, max: 20 }), unitPrice: fc.integer({ min: 0, max: 100 }), discount: fc.constantFrom(null, 0, 0.25, 0.5), status: fc.constantFrom("paid", "pending") }))], rows => {
  const paid = rows.filter(row => row.status === "paid");
  const combined = revenueByCountry([...rows, ...paid]);
  const expected = revenueByCountry(rows).map(item => ({ country: item.country, total: item.total + item.totalForPaidPlaceholder }));
  const addedByCountry = new Map<string, number>();
  for (const row of paid) {
    const amount = row.quantity * row.unitPrice * (1 - (row.discount ?? 0));
    addedByCountry.set(row.country, (addedByCountry.get(row.country) ?? 0) + amount);
  }
  const expectedTotals = new Map<string, number>();
  for (const item of revenueByCountry(rows)) expectedTotals.set(item.country, item.total);
  for (const [country, amount] of addedByCountry) expectedTotals.set(country, (expectedTotals.get(country) ?? 0) + amount);
  const expectedSorted = [...expectedTotals].map(([country, total]) => ({ country, total })).sort((a, b) => b.total - a.total || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0));
  return JSON.stringify(combined) === JSON.stringify(expectedSorted);
}, { numRuns: 200 });

// Each returned country total equals the sum of its paid rows using quantity, unit price, and discount, with null discount treated as zero.
matchesReference("totals_match_direct_paid_row_sum", [fc.array(fc.record({ id: fc.integer(), orderDate: fc.constantFrom("2024-01-01"), customer: fc.string(), email: fc.string(), country: fc.string(), product: fc.string(), quantity: fc.integer({ min: 0, max: 20 }), unitPrice: fc.integer({ min: 0, max: 100 }), discount: fc.constantFrom(null, 0, 0.25, 0.5), status: fc.constantFrom("paid", "pending", "cancelled") }))], rows => {
  const totals = new Map<string, number>();
  for (const row of rows) if (row.status === "paid") totals.set(row.country, (totals.get(row.country) ?? 0) + row.quantity * row.unitPrice * (1 - (row.discount ?? 0)));
  return [...totals].map(([country, total]) => ({ country, total })).sort((a, b) => b.total - a.total || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0));
}, { numRuns: 200 });
